  `.trim();return v(f)}function IKn(){let n=A([2,2.5,3]),e=A([4,5,6]),r=A([-1.2,-1.5,-1.8]),a=[e/4,e/3,e/2,e,e+1],h=A(a.filter(y=>y>0&&y<2*e)),s=Math.PI*n*n/(e*e)*h*(2*e-h),l=r/s,p=1,f="\u0111\u1EBFn m\u1ED9t ch\u1EEF s\u1ED1 th\u1EADp ph\xE2n",x=`
