  `.trim())}function i7n(){let n=A([120,150,180]),e=A([4,5,6]),r=A([.2,.3,.4]),a=A([15,20,25,30]),h=(s,l=1)=>Number(s).toFixed(l),g=n*a-e*a*a/2-r*a*a*a/3;return v(`
