  `.trim())}function e7n(){let n=A([140,160,180]),e=A([4,5,6]),r=A([.2,.3,.4]),a=A([20,30,40]),h=A([1.5,2,2.5]),g=A([60,70,80]),s=(I,O=1)=>Number(I).toFixed(O),l=e+h,p=(-l+Math.sqrt(l*l+4*r*(n-a)))/(2*r),f=n-e*p-r*p*p;g>=f&&(g=Math.max(1,f-5));let x=Math.max(0,e*e-4*r*(g-n)),_=(-e+Math.sqrt(x))/(2*r),y=(g-a)/h,T=Math.max(0,Math.min(_,y)),C=Math.max(0,_-y),D=(n-g)*T-e*T*T/2-r*T*T*T/3,B=(g-a)*T-h*T*T/2,H=(n-f)*p-e*p*p/2-r*p*p*p/3,q=(f-a)*p-h*p*p/2,w=H+q-(D+B);return v(`
