  `.trim())}function r7n(){let n=A([150,170,190]),e=A([4,5,6]),r=A([.2,.3,.4]),a=A([25,35,45]),h=A([1.5,2,2.5]),g=A([.08,.12,.15]),s=(O,P=1)=>Number(O).toFixed(P),l=e+h,p=(-l+Math.sqrt(l*l+4*r*(n-a)))/(2*r),f=n-e*p-r*p*p,x=(n-f)*p-e*p*p/2-r*p*p*p/3,_=(f-a)*p-h*p*p/2;n-(1+g)*a<=0&&(g=Math.max(.01,n/a-1-.01));let y=e+(1+g)*h,T=n-(1+g)*a,C=(-y+Math.sqrt(y*y+4*r*T))/(2*r),D=n-e*C-r*C*C,B=D/(1+g),H=(n-D)*C-e*C*C/2-r*C*C*C/3,q=(B-a)*C-h*C*C/2,w=g*B*C,I=x+_-(H+q+w);return v(`
