  `.trim())}function a7n(){let n=A([140,160,180]),e=A([4,5,6]),r=A([.2,.3,.4]),a=A([20,30,40]),h=A([1.5,2,2.5]),g=A([8,10,12]),s=(O,P=1)=>Number(O).toFixed(P),l=e+h,p=n-a,f=(-l+Math.sqrt(l*l+4*r*p))/(2*r),x=n-e*f-r*f*f,_=(n-x)*f-e*f*f/2-r*f*f*f/3,y=(x-a)*f-h*f*f/2,T=n-a-g;T<=0&&(g=Math.max(1,n-a-1),T=n-a-g);let C=(-l+Math.sqrt(l*l+4*r*T))/(2*r),D=n-e*C-r*C*C,B=D-g,H=(n-D)*C-e*C*C/2-r*C*C*C/3,q=(B-a)*C-h*C*C/2,w=g*C,I=_+y-(H+q+w);return v(`
