  `.trim())}function u7n(){let n=A([160,180,200]),e=A([.4,.6,.8]),r=A([20,30,40]),a=A([1.5,2,2.5]),h=A([60,70,80]),g=(q,w=1)=>Number(q).toFixed(w),l=(q=>{let w=0,I=1e9;for(let O=.01;O<=200;O+=.01){let P=Math.abs(q(O));P<I&&(I=P,w=O)}return w})(q=>n*Math.pow(q,-e)-(r+a*q)),p=n*Math.pow(l,-e);h>=p&&(h=Math.max(1,p-5));let f=Math.pow(n/h,1/e),x=(h-r)/a,_=Math.max(0,Math.min(f,x)),y=Math.max(0,f-x),T=n/(1-e)*Math.pow(_,1-e)-h*_,C=(h-r)*_-.5*a*_*_,D=n/(1-e)*Math.pow(l,1-e)-p*l,B=(p-r)*l-.5*a*l*l,H=D+B-(T+C);return v(`
