  `.trim())}function k7n(){let n=A([160,180,200]),e=A([10,12,15]),r=A([20,25,30]),a=A([1.5,2,2.5]),h=A([200,300,400]),g=(y,T=1)=>Number(y).toFixed(T),s=0,l=1/0;for(let y=.001;y<=200;y+=.001){let T=n-e*Math.log(1+y)-e*y/(1+y),C=r+a*y,D=Math.abs(T-C);D<l&&(l=D,s=y)}let p=n-e*Math.log(1+s),f=p*s,x=h+r*s+.5*a*s*s,_=f-x;return v(`
