  `.trim())}function D7n(){let n=A([150,180,200]),e=A([.05,.08,.1]),r=A([20,25,30]),a=A([1.5,2,2.5]),h=A([200,300,400]),g=(y,T=1)=>Number(y).toFixed(T),s=0,l=1/0;for(let y=0;y<=200;y+=.001){let T=n*Math.exp(-e*y)*(1-e*y),C=r+a*y,D=Math.abs(T-C);D<l&&(l=D,s=y)}let p=n*Math.exp(-e*s),f=p*s,x=h+r*s+.5*a*s*s,_=f-x;return v(`
