  `.trim())}function B7n(){let n=A([160,180,200]),e=A([2,3,4]),r=A([30,40,50]),a=A([1.5,2,2.5]),h=A([8,10,12,15]),g=(H,q=1)=>Number(H).toFixed(q);n-r-h<=0&&(h=Math.max(1,n-r-1));let s=(n-r)/(e+a),l=n-e*s,p=.5*(n-l)*s,f=.5*(l-r)*s,x=(n-r-h)/(e+a),_=n-e*x,y=_-h,T=.5*(n-_)*x,C=.5*(y-r)*x,D=h*x,B=p+f-(T+C+D);return v(`
