  `.trim())}function P7n(){let n=A([150,170,190]),e=A([2,3,4]),r=A([30,40,50]),a=A([1.5,2,2.5]),h=A([.05,.1,.15]),g=(H,q=1)=>vn&&typeof hn=="function"?hn(H,q):Number(H).toFixed(q),s=(n-r)/(e+a),l=n-e*s,p=.5*(n-l)*s,f=.5*(l-r)*s,x=(n-r*(1+h))/(e+a*(1+h)),_=n-e*x,y=_/(1+h),T=.5*(n-_)*x,C=.5*(y-r)*x,D=h*y*x,B=p+f-(T+C+D);return v(`
