    `}return e()}function NEn(n){function e(){let g=Math.PI,s=Math.floor(9/1)+1,l=1+Math.floor(Math.random()*s)*1,p=Math.pow(3*l/(g*Math.sqrt(2)),1/3),f=3*l/(g*Math.pow(p,2)),_=(g*p*Math.sqrt(p*p+f*f)).toFixed(1);return`
